const fn = $json.params.fn;
const body = $json.body || {};
const garment = { id: 'g1', code: 'A12', name: 'Vestido rojo', size: 'M', color: 'rojo', price: 150, photo_url: 'https://picsum.photos/seed/a12/600/800', status: 'in_catalog' };
const inFive = new Date(Date.now() + 5 * 60 * 1000).toISOString();
const expiredToken = String(body.p_token || '').startsWith('expired');
const responses = {
  lia_request_garment: { status: 'pending_confirmation', reservation_id: 'r1', confirm_deadline: inFive, garment },
  lia_confirm_request: { status: 'active', reservation_id: 'r1', expires_at: inFive, garment },
  lia_cancel_request: { status: 'cancelled' },
  lia_search_catalog: { items: [garment] },
  lia_customer_status: { items: [{ code: 'A12', name: 'Vestido rojo', status: 'active', expires_at: inFive, position: null }] },
  lia_expire_reservations: { expired: 0, cancelled: 0, reminders: 0, promoted: 0 },
  lia_claim_notifications: [],
  lia_mark_notification_sent: null,
  lia_get_payment_qr: expiredToken
    ? { status: 'expired', amount: 150, expires_at: new Date(Date.now() - 60000).toISOString(), seconds_left: 0, garment }
    : { status: 'active', amount: 150, expires_at: inFive, seconds_left: 300, garment },
  lia_confirm_payment: expiredToken ? { status: 'expired' } : { status: 'paid', payment_id: 'p1', garment },
};
return [{ json: { response: responses[fn] ?? { error: 'unknown function ' + fn } } }];
